fn main(){let s=std::fs::read_to_string(std::env::args().nth(1).unwrap()).unwrap();let b=incant_shader_cook::compute::cook(&s).unwrap();incant_shader_cook::compute::write_bundle(&b,std::path::Path::new(&std::env::args().nth(2).unwrap())).unwrap();let a=b.artifacts.iter().find(|a|a.backend==incant_shader_cook::Backend::Vulkan).unwrap();let m=naga::front::spv::parse_u8_slice(&a.bytes,&naga::front::spv::Options{adjust_coordinate_space:false,strict_capabilities:true,block_ctx_dump_prefix:None}).unwrap();println!("{m:#?}");}